mapper.sql:
select ee.ENTRUST_STATUS entrustStatus, nvl(efs.ENT_FINISH_AMT, 0) finishAmt, trunc(nvl(efs.ENT_FINISH_AMT, 0) / case when ee.ENTRUST_NUM is null or ee.ENTRUST_NUM = 0 then 1 else ee.ENTRUST_NUM end, 4) * 100 transactioncom, nvl(tpd.SHARE_AMT, 0) finishDealAmt, trunc(nvl(tpd.SHARE_AMT, 0) / case when ee.ENTRUST_NUM is null or ee.ENTRUST_NUM = 0 then 1 else ee.ENTRUST_NUM end, 4) * 100 tradeFinishPercent, ee.ENTRUST_NUM entrustNum, ee.FINPROD_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr, fpi.ISSUE_DATE issueDate, fpi.PAY_DATE payDate, eed.PORTFOLIO_ID portfolioId, eed.PORTFOLIO_NAME portfolioName, eea.SEC_ACCT_ID secManageAcctId, ssai.SEC_ACCT_NAME secAcctName, ee.INV_AIM businessModel, su.REAL_NAME invManagerName, ee.ENTRUST_DATE entrustDate, to_char(eea.TRANSMIT_TIME, 'hh24:mi:ss') transmitTime, to_char(eea.TRANSMIT_TIME, 'hh24:mi') transmitTimeSer, ee.ENTRUST_ID entrustId, ee.REMARK remark from ETR_ENTRUST ee left join (select listagg(t0.PORTFOLIO_ID, ',') within group (order by t0.ENTRUST_ID) AS PORTFOLIO_ID, listagg(pp.PORTFOLIO_NAME, ',') within group (order by t0.ENTRUST_ID) AS PORTFOLIO_NAME, t0.ENTRUST_ID ENTRUST_ID from ETR_ENTRUST_DETAIL t0 left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = t0.PORTFOLIO_ID
#{item}
group by t0.ENTRUST_ID) eed on ee.ENTRUST_ID = eed.ENTRUST_ID left join ETR_ENTRUST_ADD eea on ee.ENTRUST_ID = eea.ENTRUST_ID left join STL_SEC_ACCT_INFO ssai on ssai.SEC_ACCT_ID = eea.SEC_ACCT_ID left join (select sum(ENT_FINISH_AMT) ENT_FINISH_AMT, sum(FINISH_AMT) FINISH_AMT, ENTRUST_ID from ETR_FINISH_STATUS group by ENTRUST_ID) efs on ee.ENTRUST_ID = efs.ENTRUST_ID left join (select sum(t1.SHARE_AMT) SHARE_AMT, t2.ENTRUST_ID from TRD_PRODUCT_DEAL t1 left join TRD_PRODUCT_DEAL_ADD t2 on t1.TRADE_ID = t2.TRADE_ID where t1.IS_CANCEL = #{YN_N} and t1.TRADE_STATUS != #{TRADE_STATUS03} group by t2.ENTRUST_ID) tpd on tpd.ENTRUST_ID = ee.ENTRUST_ID left join FIN_PRODUCT fp on fp.FINPROD_ID = ee.FINPROD_ID left join FIN_PRODUCT_ISSUE fpi on fpi.FINPROD_ID = ee.FINPROD_ID left join SYS_USER su on su.USER_NAME = ee.INV_MANAGER_ID where fp.ISSUE_TYPE = #{ISSUE_CLASS_01} order by decode(ee.ENTRUST_STATUS, '04', 2, '05', 3, '06', 4, 1) asc,fpi.ISSUE_DATE,ee.ENTRUST_DATE,eea.TRANSMIT_TIME

sql.if:
( T.entrustStatus || '|' || sdl_es.item_value || '|' || T.finprodId || '|' || T.finprodMarketId || '|'
    || '|' || T.finprodAbbr || '|' || T.portfolioName || '|' || T.portfolioId || '|' || T.secManageAcctId
    || '|' || T.secAcctName || '|' || T.businessModel || '|' || sdl_bm.item_value
    || '|' || T.invManagerName || '|' || T.entrustId || '|' || T.remark
    like '%' || #{search} || '%'
    or decode(T.transactioncom,0,'0.00',to_char(T.transactioncom,'FM90.90'))=#{search} or to_char(T.transactioncom)=#{search}
    or decode(T.tradeFinishPercent,0,'0.00',to_char(T.tradeFinishPercent,'FM90.90'))=#{search} or to_char(T.tradeFinishPercent)=#{search}
    or decode(T.entrustNum,0,'0.00',to_char(T.entrustNum/10000,'FM999999999990.90'))=#{search} or to_char(T.entrustNum)=#{search}
    or replace(to_char(T.issueDate,'yyyy-MM-dd'),'-','/')=#{search}
    or replace(to_char(T.payDate,'yyyy-MM-dd'),'-','/')=#{search}
    or replace(to_char(T.entrustDate,'yyyy-MM-dd'),'-','/')=#{search}
    or T.transmitTime=#{search}
    )

mapper.select:
select T.entrustStatus, T.finishAmt, T.transactioncom, T.finishDealAmt, T.tradeFinishPercent, T.entrustNum, T.finprodId, T.finprodMarketId, T.finprodAbbr, T.issueDate, T.payDate, T.portfolioId, T.portfolioName, T.secManageAcctId, T.secAcctName, T.businessModel, T.invManagerName, T.entrustDate, T.transmitTime, T.transmitTimeSer, T.entrustId, T.remark from () T left join SYS_DATADICT_LIST sdl_es on T.entrustStatus=sdl_es.ITEM_CODE and sdl_es.DICT_CODE='ENTRUST_STATUS' left join SYS_DATADICT_LIST sdl_bm on T.businessModel=sdl_bm.ITEM_CODE and sdl_bm.DICT_CODE='BUSINESS_MODEL'
AND T.entrustStatus in ('02','03','04','05','06')
#{item}
#{item}
#{item}
#{item}
AND T.issueDate >= to_date(#{entrustDateStart}, 'yyyy-MM-dd')
AND T.issueDate <= to_date(#{issueDateEnd}, 'yyyy-MM-dd')
AND T.entrustDate >= to_date(#{entrustDateStart}, 'yyyy-MM-dd')
AND T.entrustDate <= to_date(#{entrustDateEnd}, 'yyyy-MM-dd')
AND T.entrustId = #{entrustId} /*指令代码查询*/
#{item}
/*指令代码查询*/
order by ${pageMode.sort} ${pageMode.direction}

     select count(1)  from  (
             select ENTRUST_ID from WFL_BID_ORDER_BID_PRICE

                ENTRUST_ID = #{entrustId}
                /*指令代码查询*/

			union all
			 select ENTRUST_ID from BID_ORDER_BID_PRICE
			 	where IS_CANCEL ='N' and TRADE_STATUS != '03'

                    AND ENTRUST_ID = #{entrustId}
                    /*指令代码查询*/

            )
